Given an array of integers, the task is to delete an element from the end of the array.Examples:Input: arr[] = [10, 20, 30, 40]Output: [10, 20, 30]Input: arr[] = [20]Output: []Table of Content[Approach 1] Using Built-In Methods[Approach 2] Using Custom Method[Approach 1] Using Built-In MethodsWe will use library methods like pop_back() in C++, remove() in Java, pop() in Python and JavaScript and removeAt() in C#.
            C++

    // C++ program to delete an element from the end 
// of an array using in-built methods

#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> arr = { 10, 20, 30, 40 };

    cout << "Array before deletion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

    // Remove the last element from the array
    arr.pop_back();

    cout << "\nArray after deletion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

    return 0;
}


            Java

    // Java program to delete an element from the end of an array
// using in-built methods

import java.util.*;

class GfG {
    public static void main(String[] args) {
        ArrayList<Integer> arr = new ArrayList<>
          						(Arrays.asList(10, 20, 30, 40));

        System.out.println("Array before deletion");
        for (int ele : arr) 
            System.out.print(ele + " ");

        // Remove the last element from the array
        arr.remove(arr.size() - 1);

        System.out.println("\nArray after deletion");
        for (int ele : arr) 
            System.out.print(ele + " ");
    }
}


